'use strict';

/**
 * Return an edit script of { op: 'equal' | 'delete' | 'insert', line: string }.
 * a and b are arrays of strings; lines are compared by exact string equality.
 * Reading equal/delete entries reconstructs a; equal/insert reconstructs b.
 * Equal entries must form a longest common subsequence: the number of deletes
 * plus inserts equals a.length + b.length - 2 * LCS(a, b).
 * Results must be deterministic. In every maximal region without an equal
 * entry, all deletes precede all inserts. No particular LCS is otherwise required.
 * Neither input may be mutated. Empty arrays and repeated/empty strings work.
 * Small changes to 20,000-line inputs must run well under a second: use a Myers
 * O((N + M) * D) algorithm (linear when D is zero), not an O(N * M) LCS table.
 * Here N/M are input lengths and D is the minimal number of inserts + deletes.
 */
function diffLines(a, b) {
  // Intern lines as integers so the inner loops compare numbers, not strings.
  const ids = new Map();
  const intern = (lines) => {
    const out = new Int32Array(lines.length);
    for (let i = 0; i < lines.length; i++) {
      let id = ids.get(lines[i]);
      if (id === undefined) {
        id = ids.size;
        ids.set(lines[i], id);
      }
      out[i] = id;
    }
    return out;
  };
  const ai = intern(a);
  const bi = intern(b);

  // One pair of V buffers suffices: bisect finishes before recursing.
  const maxD = Math.ceil((a.length + b.length) / 2);
  const size = 2 * maxD + 2;
  const v1 = new Int32Array(size);
  const v2 = new Int32Array(size);

  const raw = [];
  const emit = (op, from, to, src) => {
    for (let i = from; i < to; i++) raw.push({ op, line: src[i] });
  };

  // Myers middle-snake bisection; returns the split point [x, y] in absolute
  // coordinates such that an optimal path passes through it.
  const bisect = (aLo, aHi, bLo, bHi) => {
    const n = aHi - aLo;
    const m = bHi - bLo;
    const dMax = Math.ceil((n + m) / 2);
    const off = dMax;
    const len = 2 * dMax + 2;
    v1.fill(-1, 0, len);
    v2.fill(-1, 0, len);
    v1[off + 1] = 0;
    v2[off + 1] = 0;
    const delta = n - m;
    const front = (delta & 1) !== 0;
    let k1start = 0;
    let k1end = 0;
    let k2start = 0;
    let k2end = 0;
    for (let d = 0; d <= dMax; d++) {
      for (let k1 = -d + k1start; k1 <= d - k1end; k1 += 2) {
        const k1o = off + k1;
        let x1 = k1 === -d || (k1 !== d && v1[k1o - 1] < v1[k1o + 1])
          ? v1[k1o + 1]
          : v1[k1o - 1] + 1;
        let y1 = x1 - k1;
        while (x1 < n && y1 < m && ai[aLo + x1] === bi[bLo + y1]) {
          x1++;
          y1++;
        }
        v1[k1o] = x1;
        if (x1 > n) {
          k1end += 2;
        } else if (y1 > m) {
          k1start += 2;
        } else if (front) {
          const k2o = off + delta - k1;
          if (k2o >= 0 && k2o < len && v2[k2o] !== -1 && x1 >= n - v2[k2o]) {
            return [aLo + x1, bLo + y1];
          }
        }
      }
      for (let k2 = -d + k2start; k2 <= d - k2end; k2 += 2) {
        const k2o = off + k2;
        let x2 = k2 === -d || (k2 !== d && v2[k2o - 1] < v2[k2o + 1])
          ? v2[k2o + 1]
          : v2[k2o - 1] + 1;
        let y2 = x2 - k2;
        while (x2 < n && y2 < m && ai[aHi - 1 - x2] === bi[bHi - 1 - y2]) {
          x2++;
          y2++;
        }
        v2[k2o] = x2;
        if (x2 > n) {
          k2end += 2;
        } else if (y2 > m) {
          k2start += 2;
        } else if (!front) {
          const k1o = off + delta - k2;
          if (k1o >= 0 && k1o < len && v1[k1o] !== -1) {
            const x1 = v1[k1o];
            if (x1 >= n - x2) return [aLo + x1, bLo + x1 - (k1o - off)];
          }
        }
      }
    }
    throw new Error('diffLines: middle snake not found');
  };

  const solve = (aLo, aHi, bLo, bHi) => {
    let pre = aLo;
    while (pre < aHi && bLo + (pre - aLo) < bHi && ai[pre] === bi[bLo + (pre - aLo)]) pre++;
    const prefix = pre - aLo;
    emit('equal', aLo, pre, a);
    aLo = pre;
    bLo += prefix;

    let suffix = 0;
    while (aHi - suffix > aLo && bHi - suffix > bLo && ai[aHi - 1 - suffix] === bi[bHi - 1 - suffix]) {
      suffix++;
    }
    const aEnd = aHi - suffix;
    const bEnd = bHi - suffix;

    if (aLo === aEnd || bLo === bEnd) {
      emit('delete', aLo, aEnd, a);
      emit('insert', bLo, bEnd, b);
    } else {
      const [x, y] = bisect(aLo, aEnd, bLo, bEnd);
      solve(aLo, x, bLo, y);
      solve(x, aEnd, y, bEnd);
    }
    emit('equal', aEnd, aHi, a);
  };

  solve(0, a.length, 0, b.length);

  // Within each maximal non-equal run, place all deletes before all inserts.
  const script = [];
  let i = 0;
  while (i < raw.length) {
    if (raw[i].op === 'equal') {
      script.push(raw[i++]);
      continue;
    }
    let j = i;
    while (j < raw.length && raw[j].op !== 'equal') j++;
    for (let k = i; k < j; k++) if (raw[k].op === 'delete') script.push(raw[k]);
    for (let k = i; k < j; k++) if (raw[k].op === 'insert') script.push(raw[k]);
    i = j;
  }
  return script;
}

/**
 * Return unified hunks: [{ oldStart, oldLines, newStart, newLines, lines }].
 * context is a nonnegative integer, default 3. Hunk lines are original strings
 * prefixed with ' ' (equal), '-' (delete), or '+' (insert); remove exactly one
 * prefix to recover a line, even when the original starts with a prefix itself.
 * oldLines counts context + deletes; newLines counts context + inserts.
 * Include up to context unchanged lines before/after each changed region.
 * Merge regions if the intervening unchanged gap is <= 2 * context (their
 * context would touch or overlap). Do not duplicate context in merged hunks.
 * Starts are 1-based, except a zero-line range names the line BEFORE the range:
 * oldLines === 0 uses the preceding old line number (0 for insertion at top),
 * and newLines === 0 uses the preceding new line number (0 for deletion at top).
 * Coordinates refer to the complete original a and result b, not a local hunk.
 * Identical inputs return []. Use diffLines' minimality and deletion ordering.
 * Neither input may be mutated. Inputs follow the diffLines contract.
 */
function unifiedHunks(a, b, { context = 3 } = {}) {
  if (!Number.isInteger(context) || context < 0) {
    throw new RangeError('context must be a nonnegative integer');
  }
  const script = diffLines(a, b);

  // Maximal changed regions as [first, last] script indices.
  const regions = [];
  for (let i = 0; i < script.length; i++) {
    if (script[i].op === 'equal') continue;
    let j = i;
    while (j + 1 < script.length && script[j + 1].op !== 'equal') j++;
    const prev = regions[regions.length - 1];
    if (prev && i - prev[1] - 1 <= 2 * context) prev[1] = j;
    else regions.push([i, j]);
    i = j;
  }
  if (regions.length === 0) return [];

  // Old/new line counts consumed before each script index.
  const hunks = [];
  let r = 0;
  let oldPos = 0;
  let newPos = 0;
  let start = Math.max(0, regions[0][0] - context);
  let hunk = null;
  for (let i = 0; i < script.length && r < regions.length; i++) {
    const { op, line } = script[i];
    if (i === start) {
      hunk = { oldStart: oldPos, oldLines: 0, newStart: newPos, newLines: 0, lines: [] };
    }
    if (hunk) {
      if (op === 'equal') {
        hunk.lines.push(' ' + line);
        hunk.oldLines++;
        hunk.newLines++;
      } else if (op === 'delete') {
        hunk.lines.push('-' + line);
        hunk.oldLines++;
      } else {
        hunk.lines.push('+' + line);
        hunk.newLines++;
      }
    }
    if (op !== 'insert') oldPos++;
    if (op !== 'delete') newPos++;
    if (hunk && i === Math.min(script.length - 1, regions[r][1] + context)) {
      if (hunk.oldLines > 0) hunk.oldStart++;
      if (hunk.newLines > 0) hunk.newStart++;
      hunks.push(hunk);
      hunk = null;
      r++;
      if (r < regions.length) start = regions[r][0] - context;
    }
  }
  return hunks;
}

/**
 * Return a new array by applying unified hunks to a, without mutating either.
 * Hunk old coordinates refer to the original a: apply in the given order,
 * tracking offsets caused by earlier insertions/deletions. Hunks must be
 * nonoverlapping and ordered; their counts and new coordinates must agree with
 * their lines. Verify every ' ' and '-' line exactly against a before consuming
 * it. Unmentioned original lines are retained. An empty hunk array returns a copy.
 * A mismatch or malformed/nonapplicable hunk throws Error with a message
 * containing 'hunk <index> does not apply', where index is zero-based.
 */
function applyHunks(a, hunks) {
  if (!Array.isArray(hunks)) throw new TypeError('hunks must be an array');
  const out = [];
  let cursor = 0;
  const isCount = (v) => Number.isInteger(v) && v >= 0;

  for (let h = 0; h < hunks.length; h++) {
    const fail = (reason) => new Error(`hunk ${h} does not apply: ${reason}`);
    const hunk = hunks[h];
    if (hunk === null || typeof hunk !== 'object') throw fail('not an object');
    const { oldStart, oldLines, newStart, newLines, lines } = hunk;
    if (!isCount(oldStart) || !isCount(oldLines) || !isCount(newStart) || !isCount(newLines)) {
      throw fail('starts and counts must be nonnegative integers');
    }
    if (!Array.isArray(lines) || lines.length === 0) throw fail('lines must be a nonempty array');

    let oldCount = 0;
    let newCount = 0;
    for (const l of lines) {
      if (typeof l !== 'string' || l.length === 0) throw fail('malformed line');
      const p = l[0];
      if (p === ' ') {
        oldCount++;
        newCount++;
      } else if (p === '-') {
        oldCount++;
      } else if (p === '+') {
        newCount++;
      } else {
        throw fail(`invalid line prefix ${JSON.stringify(p)}`);
      }
    }
    if (oldCount !== oldLines || newCount !== newLines) throw fail('counts disagree with lines');

    if (oldLines > 0 && oldStart === 0) throw fail('oldStart must be 1-based');
    const from = oldLines > 0 ? oldStart - 1 : oldStart;
    if (from < cursor) throw fail('overlaps or precedes an earlier hunk');
    if (from + oldLines > a.length) throw fail('old range exceeds input');

    for (let i = cursor; i < from; i++) out.push(a[i]);
    const expectedNewStart = newLines > 0 ? out.length + 1 : out.length;
    if (newStart !== expectedNewStart) {
      throw fail(`newStart ${newStart} does not match expected ${expectedNewStart}`);
    }

    let pos = from;
    for (const l of lines) {
      const text = l.slice(1);
      if (l[0] === '+') {
        out.push(text);
        continue;
      }
      if (a[pos] !== text) throw fail(`line ${pos + 1} mismatch`);
      if (l[0] === ' ') out.push(text);
      pos++;
    }
    cursor = pos;
  }
  for (let i = cursor; i < a.length; i++) out.push(a[i]);
  return out;
}

module.exports = { diffLines, unifiedHunks, applyHunks };

'use strict';
const assert = require('node:assert/strict');
const { diffLines, unifiedHunks, applyHunks } = require('./src/diff');

function lcs(a, b) {
  const dp = Array.from({ length: a.length + 1 }, () => new Array(b.length + 1).fill(0));
  for (let i = a.length - 1; i >= 0; i--) for (let j = b.length - 1; j >= 0; j--) {
    dp[i][j] = a[i] === b[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1]);
  }
  return dp[0][0];
}
let seed = 12345;
const rnd = (n) => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed % n; };
const alpha = ['', 'x', ' x', '-x', '+x', 'y', 'z'];
const gen = () => Array.from({ length: rnd(14) }, () => alpha[rnd(alpha.length)]);

for (let t = 0; t < 20000; t++) {
  const a = gen();
  const b = rnd(3) === 0 ? a.slice() : gen();
  const ac = a.slice(), bc = b.slice();
  const s = diffLines(a, b);
  assert.deepEqual(s, diffLines(a, b));
  assert.deepEqual(s.filter((e) => e.op !== 'insert').map((e) => e.line), a);
  assert.deepEqual(s.filter((e) => e.op !== 'delete').map((e) => e.line), b);
  const ed = s.filter((e) => e.op !== 'equal').length;
  assert.equal(ed, a.length + b.length - 2 * lcs(a, b));
  for (let i = 1; i < s.length; i++) assert.ok(!(s[i - 1].op === 'insert' && s[i].op === 'delete'));
  for (const context of [0, 1, 2, 3, 5]) {
    const hs = unifiedHunks(a, b, { context });
    if (ed === 0) assert.deepEqual(hs, []);
    assert.deepEqual(applyHunks(a, hs), b);
    // reference coordinates from complete coords
    for (const h of hs) {
      const old = h.lines.filter((l) => l[0] !== '+').map((l) => l.slice(1));
      const nw = h.lines.filter((l) => l[0] !== '-').map((l) => l.slice(1));
      const o = h.oldLines ? h.oldStart - 1 : h.oldStart;
      const n = h.newLines ? h.newStart - 1 : h.newStart;
      assert.deepEqual(a.slice(o, o + h.oldLines), old);
      assert.deepEqual(b.slice(n, n + h.newLines), nw);
      // context limits
      let lead = 0; while (h.lines[lead][0] === ' ') lead++;
      let trail = 0; while (h.lines[h.lines.length - 1 - trail][0] === ' ') trail++;
      assert.ok(lead <= context && trail <= context);
      assert.ok(lead === context || o === 0);
      assert.ok(trail === context || o + h.oldLines === a.length);
    }
    for (let i = 1; i < hs.length; i++) {
      const prevEnd = (hs[i - 1].oldLines ? hs[i - 1].oldStart - 1 : hs[i - 1].oldStart) + hs[i - 1].oldLines;
      const start = hs[i].oldLines ? hs[i].oldStart - 1 : hs[i].oldStart;
      assert.ok(start - prevEnd > 0, 'gap');
    }
  }
  assert.deepEqual(a, ac); assert.deepEqual(b, bc);
}

// apply errors
const a = ['a', 'b', 'c'];
const hs = unifiedHunks(a, ['a', 'B', 'c'], { context: 0 });
assert.throws(() => applyHunks(['a', 'X', 'c'], hs), /hunk 0 does not apply/);
assert.throws(() => applyHunks(a, [hs[0], hs[0]]), /hunk 1 does not apply/);
assert.throws(() => applyHunks(a, [{ ...hs[0], newStart: 5 }]), /hunk 0 does not apply/);
assert.throws(() => applyHunks(a, [{ ...hs[0], oldLines: 2 }]), /hunk 0 does not apply/);
assert.deepEqual(applyHunks(a, []), a);
console.log(unifiedHunks(['a'], ['x', 'a'], { context: 0 }), unifiedHunks(['a', 'b'], ['b'], { context: 0 }));

// perf
const big = Array.from({ length: 20000 }, (_, i) => `line ${i % 50}`);
const big2 = big.slice(); big2[100] = 'changed'; big2.splice(15000, 3); big2.splice(9000, 0, 'new', 'lines');
let t0 = Date.now(); const hb = unifiedHunks(big, big2); assert.deepEqual(applyHunks(big, hb), big2);
console.log('small change ms', Date.now() - t0);
t0 = Date.now(); diffLines(big, big); console.log('identical ms', Date.now() - t0);
const rev = Array.from({ length: 20000 }, (_, i) => `other ${i}`);
t0 = Date.now(); diffLines(big, rev); console.log('disjoint ms', Date.now() - t0);
console.log('ok');
